//! Many places at once (Part III F11): every player's [`Place`], the ground of every body
//! someone has been to, and the tick's pass over each occupied store.
//!
//! The home world (its sky and the Moon included) is the world's own terrain and entity store,
//! exactly as before. Every other store (a space body's ground, free flight) is a
//! [`BodyWorld`]: its own terrain (generated by a [`crate::place::BodyGenerator`]), entities and
//! fluid schedule, created the first time someone arrives and kept (frozen) while nobody is
//! there.
//!
//! [`WorldState::simulate_tick`] runs the world pass over the home store (with only the
//! players at home), then one ground pass per occupied store: the store's ground is swapped
//! into the world, only its players take part, and the world-level systems (clock, economy,
//! the Descents, people, quests, ...) are left to the world pass. Entity ids and revisions stay
//! unique across stores (every pass continues the same counters), so replication keys need no
//! store. Inside every pass, entities outside the regions round the store's occupants are
//! frozen ([`crate::place::occupied_cells`]).

use std::collections::{BTreeMap, BTreeSet};

use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::{
    entity::{Entity, EntityKind, EntityStore},
    event::TickOutput,
    hash::StateHasher,
    ids::{PlayerId, SimulationTick},
    input::TickInputs,
    place::{
        ARRIVAL_CHUNK_RADIUS, BodySource, MAX_AWAKE_STORES_PER_TICK, Place, RegionId,
        STORE_STREAM_CHUNKS_PER_TICK, StoreKey, occupied_cells,
    },
    position::{Frame, FrameShift, Reframe, WorldPos},
    rig::DrillState,
    terrain::{
        ChunkPosition, PackedChunks, TILE_SIZE, Terrain, TileChange, TileDiffs, TilePosition,
    },
};

use super::{ActiveDrillTimer, FluidSchedule, WorldState};

/// The ground of one store other than the home world's: terrain, entities and fluids.
///
/// A generated space body's ground is the polar track's round planet ([`Terrain::planet`],
/// from [`crate::place::planet_params_for`]): its strip wraps, its tiles are ring segments and
/// its gravity zone ([`super::planet::planet_gravity_zone`]) is the store's own field zone.
/// Free flight's store is vacuum; a key that names no body of the world's space gets the flat
/// test ground (tests and tools).
#[derive(Clone, Debug)]
pub struct BodyWorld {
    pub(crate) store: StoreKey,
    /// The world's galaxy key (its seed and space generator, Wave 14 finish).
    pub(crate) seed: crate::space::SpaceSeed,
    pub(crate) terrain: Terrain,
    pub(crate) entities: EntityStore,
    pub(crate) fluids: FluidSchedule,
    /// The store's own field zones (a planet's gravity), swapped in with its ground; rebuilt
    /// from the ground, never saved.
    pub(crate) fields: crate::field::FieldZones,
    /// Each player's map of this body (Wave 12 systems: a body's map is its own, apart from
    /// the home world's), swapped in with its ground; tiles keyed round the lap.
    pub(crate) discovered: BTreeMap<PlayerId, super::DiscoveredTiles>,
}

impl BodyWorld {
    /// A fresh store's ground (no edits, no entities) in `frame`. `None` for the home store.
    #[must_use]
    pub fn generate(store: StoreKey, seed: crate::space::SpaceSeed, frame: Frame) -> Option<Self> {
        Self::build(store, seed, frame, Vec::new())
    }

    /// The store's ground in `frame` with `edits` over the generated tiles.
    fn build(
        store: StoreKey,
        seed: crate::space::SpaceSeed,
        frame: Frame,
        edits: Vec<(ChunkPosition, TileDiffs)>,
    ) -> Option<Self> {
        let planet = match store {
            StoreKey::Body(key) => crate::place::planet_params_for(seed, key),
            StoreKey::Home | StoreKey::Space => None,
        };
        let mut fields = crate::field::FieldZones::default();
        let terrain = if let Some(params) = planet {
            let _id = fields.insert(super::planet::planet_gravity_zone(&params));
            // A settled body's towns resolve by id from the moment its ground exists (Wave 12:
            // a store built fresh, restored from a save or received in a keyframe).
            if params.folk != 0 {
                crate::alien::town::register(&params);
            }
            Terrain::planet_with(params, frame, edits)
        } else {
            Terrain::for_body(BodySource::for_store(store, seed.seed)?, frame, edits)
        };
        Some(Self {
            store,
            seed,
            terrain,
            entities: EntityStore::new(),
            fluids: FluidSchedule::default(),
            fields,
            discovered: BTreeMap::new(),
        })
    }

    /// `player`'s map of this ground (Wave 12 systems).
    #[must_use]
    pub fn discovered(&self, player: PlayerId) -> Option<&super::DiscoveredTiles> {
        self.discovered.get(&player)
    }

    /// The store this is the ground of.
    #[must_use]
    pub const fn store(&self) -> StoreKey {
        self.store
    }

    /// The store's terrain.
    #[must_use]
    pub const fn terrain(&self) -> &Terrain {
        &self.terrain
    }

    /// The store's entities.
    #[must_use]
    pub const fn entities(&self) -> &EntityStore {
        &self.entities
    }

    /// The round body this store is the ground of, if it is one.
    #[must_use]
    pub const fn planet(&self) -> Option<&crate::planet::PlanetGround> {
        self.terrain.planet_ground()
    }

    /// Whether nothing in the store differs from a fresh one.
    #[must_use]
    pub fn is_pristine(&self) -> bool {
        self.terrain.edited_chunk_count() == 0 && self.entities.is_empty()
    }

    /// A fingerprint of what generates this ground (a restore under a different build fails
    /// instead of silently loading different ground).
    #[must_use]
    pub fn fingerprint(&self) -> u64 {
        if let Some(planet) = self.terrain.planet_ground() {
            let mut hash = StateHasher::new();
            // A body nobody settled keeps the fingerprint it had before the aliens' `folk`
            // byte (Wave 12): saved bodies of earlier builds load unchanged.
            let params = planet.params();
            if params.folk == 0 {
                hash.write_serialized(&(
                    params.seed,
                    params.radius,
                    params.gravity_milli,
                    params.theme,
                ));
            } else {
                hash.write_serialized(params);
            }
            let column = 0;
            let row = crate::planet::BodyGround::surface_row(planet, column);
            for tile in planet.chunk_tiles(ChunkPosition::of(TilePosition { x: column, y: row })) {
                hash.write_u64(tile.code());
            }
            return hash.finish().get();
        }
        self.terrain
            .body_source()
            .map_or(0, |source| source.fingerprint())
    }

    fn hash_into(&self, hash: &mut StateHasher) {
        hash.write_u64(self.fingerprint());
        hash.write_serialized(&self.terrain.frame());
        hash.write_u64(u64::try_from(self.terrain.stored_tile_count()).unwrap_or(u64::MAX));
        hash.write_u64(self.terrain.digest());
        hash.write_u64(u64::try_from(self.entities.len()).unwrap_or(u64::MAX));
        for entity in self.entities.iter() {
            hash.write_serialized(entity);
        }
    }
}

/// How a [`BodyWorld`] is saved and sent in keyframes: the store and seed its ground is
/// rebuilt from, the generator's fingerprint and the terrain digest (both checked on load),
/// its frame, its edited chunks packed ([`crate::terrain::PackedChunks`], runs of equal tiles,
/// base64 in JSON), its entities and fluid schedule.
#[derive(Deserialize, Serialize)]
struct BodyWorldData {
    store: StoreKey,
    seed: u64,
    /// The space generator the body's world was made by (Wave 14 finish; a save of Waves
    /// 11-13 has none: V1).
    #[serde(default)]
    space_generator: crate::space::SpaceGenerator,
    fingerprint: u64,
    digest: u64,
    frame: Frame,
    #[serde(default)]
    packed: PackedChunks,
    #[serde(default)]
    entities: EntityStore,
    #[serde(default)]
    fluids: FluidSchedule,
    /// Each player's map of the body (Wave 12 systems).
    #[serde(default, with = "crate::pair_list")]
    discovered: BTreeMap<PlayerId, super::DiscoveredTiles>,
}

impl Serialize for BodyWorld {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        BodyWorldData {
            store: self.store,
            seed: self.seed.seed,
            space_generator: self.seed.generator,
            fingerprint: self.fingerprint(),
            digest: self.terrain.digest(),
            frame: self.terrain.frame(),
            packed: PackedChunks(self.terrain.edited_chunk_diffs()),
            entities: self.entities.clone(),
            fluids: self.fluids.clone(),
            discovered: self.discovered.clone(),
        }
        .serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for BodyWorld {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let data = BodyWorldData::deserialize(deserializer)?;
        let seed = crate::space::SpaceSeed::new(data.seed, data.space_generator);
        let fresh = Self::build(data.store, seed, data.frame, Vec::new())
            .ok_or_else(|| serde::de::Error::custom("the home store is not a body world"))?;
        if fresh.fingerprint() != data.fingerprint && fresh.planet().is_some() {
            // The body's ground was regenerated by a newer build (Wave 12: a space theme now
            // lands on its own planet theme, where Wave 11 laid barren ground, and settled
            // bodies carry their alien towns). Its edits, creatures and fluids belong to the old
            // ground, so the body starts fresh rather than the whole save failing to load. Every
            // Wave 12 re-theme (the wild and frontier worlds, the aliens' towns) relies on it.
            return Ok(fresh);
        }
        // The saved edits' own digest: when the ground has grown since the save (Wave 14
        // finish: the Wave 12 worlds' lairs under their landmarks), an old edit equal to the new
        // generated tile (a tunnel dug where the hall now is) stops counting as an edit, so the
        // rebuilt digest is smaller though every edit arrived whole. Its edits laid over the new
        // ground are exactly the player's ground, so it loads.
        let saved_edits_digest = Terrain::edits_digest(&data.packed.0);
        let mut world = Self::build(data.store, seed, data.frame, data.packed.0)
            .ok_or_else(|| serde::de::Error::custom("the home store is not a body world"))?;
        if world.fingerprint() != data.fingerprint {
            return Err(serde::de::Error::custom(format!(
                "body {:?} was generated by a different build (fingerprint {:#x}, now {:#x})",
                data.store,
                data.fingerprint,
                world.fingerprint()
            )));
        }
        let regrown = world.planet().is_some() && saved_edits_digest == data.digest;
        if world.terrain.digest() != data.digest && !regrown {
            return Err(serde::de::Error::custom(format!(
                "body {:?} ground digest mismatch (expected {:#x}, got {:#x})",
                data.store,
                data.digest,
                world.terrain.digest()
            )));
        }
        world.entities = data.entities;
        world.fluids = data.fluids;
        world.discovered = data.discovered;
        Ok(world)
    }
}

/// Every player's place and the ground of every store other than the home world's.
#[derive(Clone, Debug, Default, Deserialize, Serialize)]
pub struct Places {
    /// Players (live or parked) away from the home store, and where they are. A player
    /// without an entry is in the home store: on the home world, or on the Moon when the
    /// actor stands in its footprint ([`WorldState::place_of`]).
    #[serde(default, with = "crate::pair_list")]
    players: BTreeMap<PlayerId, Place>,
    /// The ground of every store someone has been to.
    #[serde(default, with = "crate::pair_list")]
    pub(super) stores: BTreeMap<StoreKey, BodyWorld>,
    /// The last store served when more stores were occupied than the per-tick budget allows
    /// ([`MAX_AWAKE_STORES_PER_TICK`]); the next tick starts after it.
    #[serde(default)]
    cursor: Option<StoreKey>,
}

impl Places {
    /// Whether nobody has ever left the home store.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.players.is_empty() && self.stores.is_empty() && self.cursor.is_none()
    }

    /// Players away from the home store and their places, in id order.
    pub fn away(&self) -> impl Iterator<Item = (PlayerId, Place)> + '_ {
        self.players.iter().map(|(player, place)| (*player, *place))
    }

    /// The stores with ground, in key order.
    pub fn stores(&self) -> impl Iterator<Item = (StoreKey, &BodyWorld)> + '_ {
        self.stores.iter().map(|(key, world)| (*key, world))
    }

    /// One store's ground.
    #[must_use]
    pub fn store(&self, key: StoreKey) -> Option<&BodyWorld> {
        self.stores.get(&key)
    }

    /// Whether `player` is in the home store.
    #[must_use]
    pub fn is_home(&self, player: PlayerId) -> bool {
        self.players
            .get(&player)
            .is_none_or(|place| place.store().is_home())
    }

    /// Keeps only `viewer`'s own maps of the bodies (a keyframe for `viewer`; Wave 13 QA:
    /// body maps travel by relevance, a player's map only to that player, as the home map
    /// does). A spectator gets none.
    pub(crate) fn keep_maps_of(&mut self, viewer: Option<PlayerId>) {
        for world in self.stores.values_mut() {
            world.discovered.retain(|player, _| Some(*player) == viewer);
        }
    }

    /// Every player with a map of some body (tests and reports).
    #[must_use]
    pub fn map_holders(&self) -> BTreeSet<PlayerId> {
        self.stores
            .values()
            .flat_map(|world| world.discovered.keys().copied())
            .collect()
    }

    /// Drops a removed player's place.
    pub(crate) fn forget(&mut self, player: PlayerId) {
        self.players.remove(&player);
        for world in self.stores.values_mut() {
            world.discovered.remove(&player);
        }
    }

    /// Hashes the places of the live players `live` accepts and the stores `sees_store`
    /// accepts (the budget cursor is host bookkeeping; parked players' places stay on the
    /// host).
    pub(crate) fn hash_into(
        &self,
        hash: &mut StateHasher,
        live: &impl Fn(PlayerId) -> bool,
        sees_store: &impl Fn(StoreKey) -> bool,
    ) {
        if self.players.is_empty() && self.stores.is_empty() {
            return;
        }
        let away: Vec<(&PlayerId, &Place)> = self
            .players
            .iter()
            .filter(|(player, _)| live(**player))
            .collect();
        hash.write_serialized(&away);
        for (key, world) in &self.stores {
            if sees_store(*key) {
                hash.write_serialized(key);
                world.hash_into(hash);
            }
        }
    }
}

/// Free flight's rigs this far apart (sectors, either axis) or nearer share a frame (Wave 13
/// QA: farther, `f32` positions in one frame lose their sub-pixel grid).
pub const SPACE_GROUP_LINK_SECTORS: u64 = 4;

/// A group of free flight's rigs near each other and the frame their positions are measured
/// in ([`WorldState::space_groups`]).
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SpaceGroup {
    /// Its rigs, in id order.
    pub members: Vec<PlayerId>,
    /// Its own frame (round its first rig); `None` for the group measured in the store's.
    pub frame: Option<Frame>,
}

/// What the running pass is (never saved, hashed or replicated).
#[derive(Clone, Debug, Default)]
pub struct PlacePass {
    /// The store whose ground is swapped in (`Home` outside a pass).
    store: StoreKey,
    /// Whether a ground pass of another store is running (world-level systems skip).
    ground_only: bool,
    /// The awake region cells of the running pass (`None`: everything is awake, as on every
    /// world before V11).
    awake_cells: Option<BTreeSet<(i64, i64)>>,
    /// Moves asked for during a pass, applied after the last pass of the tick.
    pending_moves: Vec<(PlayerId, Place, WorldPos)>,
    /// Whether a pass is running at all.
    running: bool,
    /// The players set aside for the running pass (they are in another store this tick; the
    /// world pass's cleanups must not mistake them for players who left the world).
    set_aside: BTreeSet<PlayerId>,
    /// Whether the world ticks by region (read from the home terrain at the start of the
    /// tick).
    regions: bool,
    /// The world's seed (read from the home terrain at the start of the tick).
    home_seed: u64,
    /// The home store's frame and settings (read at the start of the tick).
    home_frame: Frame,
    home_settings: Option<crate::worldgen::WorldSettings>,
}

/// Why [`WorldState::move_to_place`] refused.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PlaceError {
    /// No such player.
    UnknownPlayer,
    /// The destination is outside the place's ground.
    OutsideGround,
}

/// The per-player state that goes with a player in and out of a pass.
#[derive(Default)]
struct PassPlayers {
    players: BTreeMap<PlayerId, crate::player::Player>,
    drills: BTreeMap<PlayerId, DrillState>,
    timers: BTreeMap<PlayerId, ActiveDrillTimer>,
}

impl WorldState {
    /// Whether this world simulates by region (V11+ worlds: entities far from every occupant
    /// freeze). Older worlds tick every awake entity, exactly as before.
    #[must_use]
    pub const fn ticks_by_region(&self) -> bool {
        if self.place_pass.store.is_home() {
            self.terrain.settings().generator.has_descents()
        } else {
            // A ground pass's terrain is the body's; the world's answer was taken at the
            // start of the tick.
            self.place_pass.regions
        }
    }

    /// Every player's place registry and the stores' ground.
    #[must_use]
    pub const fn places(&self) -> &Places {
        &self.places
    }

    /// Where `player_id` is: the place recorded for a player away from the home store, else
    /// the Moon when its actor is in the Moon's footprint, else the home world.
    #[must_use]
    pub fn place_of(&self, player_id: PlayerId) -> Place {
        if let Some(place) = self.places.players.get(&player_id) {
            return *place;
        }
        // Free flight under the Star Drive (Wave 11 flight): the rig's home-store slot is
        // parked over the Moon while its flight state carries its exact space position.
        if self
            .players
            .get(&player_id)
            .is_some_and(|player| player.flight.away())
        {
            return Place::Space;
        }
        if self.place_pass.store.is_home()
            && self
                .actor_tile(player_id)
                .is_some_and(|tile| self.on_moon(tile))
        {
            return Place::OnBody(crate::place::BodyId::Moon);
        }
        Place::HOME
    }

    /// The store `player_id`'s place lives in.
    #[must_use]
    pub fn store_of(&self, player_id: PlayerId) -> StoreKey {
        self.places
            .players
            .get(&player_id)
            .map_or(StoreKey::Home, |place| place.store())
    }

    /// The store whose ground the running pass works on (the home store outside the tick).
    /// Systems that behave differently on a body read this inside the tick (the planet's
    /// gravity zone and lap wrap come with its ground; life support, take-off and the beacon on
    /// a body are `world/body_flight.rs`'s).
    #[must_use]
    pub const fn active_store(&self) -> StoreKey {
        self.place_pass.store
    }

    /// Whether the tick runs by stores (a pass of [`Self::simulate_places`] is under way).
    #[must_use]
    pub(super) const fn place_pass_running(&self) -> bool {
        self.place_pass.running
    }

    /// Whether a ground pass of a store other than the home world's is running.
    #[must_use]
    pub const fn in_ground_pass(&self) -> bool {
        self.place_pass.ground_only
    }

    /// `player_id`'s map of `store`'s ground (a body's own map, Wave 12 systems; the home
    /// world's map is [`Self::discovered_tiles`]).
    #[must_use]
    pub fn store_discovered(
        &self,
        store: StoreKey,
        player_id: PlayerId,
    ) -> Option<&super::DiscoveredTiles> {
        if store.is_home() {
            return self.discovered_tiles(player_id);
        }
        self.places.stores.get(&store)?.discovered(player_id)
    }

    /// The terrain of `store` (outside the tick).
    #[must_use]
    pub fn store_terrain(&self, store: StoreKey) -> Option<&Terrain> {
        if store == self.place_pass.store {
            return Some(&self.terrain);
        }
        self.places.stores.get(&store).map(BodyWorld::terrain)
    }

    /// The entities of `store` (outside the tick).
    #[must_use]
    pub fn store_entities(&self, store: StoreKey) -> Option<&EntityStore> {
        if store == self.place_pass.store {
            return Some(&self.entities);
        }
        self.places.stores.get(&store).map(BodyWorld::entities)
    }

    /// The frame `store`'s positions are measured in.
    #[must_use]
    pub fn store_frame(&self, store: StoreKey) -> Option<Frame> {
        self.store_terrain(store).map(Terrain::frame)
    }

    /// The groups of free flight's rigs, each with the frame its rigs' positions are measured
    /// in (Wave 13 QA: per-occupant frames, see [`SpaceGroup`]). The first group (the store's
    /// first rig's) is measured in the store's own frame; a group farther than
    /// [`SPACE_GROUP_LINK_SECTORS`] from every other rig has its own, round its first rig. A
    /// pure function of the rigs' exact space positions, so every peer groups alike.
    #[must_use]
    pub fn space_groups(&self) -> Vec<SpaceGroup> {
        let rigs: Vec<(PlayerId, WorldPos)> = self
            .players
            .iter()
            .filter(|(id, _)| self.store_of(**id) == StoreKey::Space)
            .map(|(id, rig)| (*id, rig.flight.pos))
            .collect();
        if rigs.is_empty() {
            return Vec::new();
        }
        // Linked when within reach of each other (single linkage), in id order.
        let mut group_of: Vec<usize> = (0..rigs.len()).collect();
        let near = |a: WorldPos, b: WorldPos| {
            a.sector_x.abs_diff(b.sector_x) <= SPACE_GROUP_LINK_SECTORS
                && a.sector_y.abs_diff(b.sector_y) <= SPACE_GROUP_LINK_SECTORS
        };
        for i in 0..rigs.len() {
            for j in 0..i {
                if near(rigs[i].1, rigs[j].1) {
                    let (from, to) = (group_of[i].max(group_of[j]), group_of[i].min(group_of[j]));
                    for group in &mut group_of {
                        if *group == from {
                            *group = to;
                        }
                    }
                }
            }
        }
        let mut groups: Vec<SpaceGroup> = Vec::new();
        let mut index: BTreeMap<usize, usize> = BTreeMap::new();
        for (rig, group) in group_of.iter().enumerate() {
            let at = *index.entry(*group).or_insert_with(|| {
                let anchor = rigs[rig].1;
                groups.push(SpaceGroup {
                    members: Vec::new(),
                    frame: (!groups.is_empty())
                        .then(|| Frame::floating_at(anchor.sector_x, anchor.sector_y)),
                });
                groups.len() - 1
            });
            groups[at].members.push(rigs[rig].0);
        }
        groups
    }

    /// The frame `player_id`'s rig position is measured in: its store's, or its far group's
    /// own in free flight (Wave 13 QA).
    #[must_use]
    pub fn player_frame(&self, player_id: PlayerId) -> Option<Frame> {
        let store = self.store_of(player_id);
        if store == StoreKey::Space
            && let Some(group) = self
                .space_groups()
                .into_iter()
                .find(|group| group.members.contains(&player_id))
            && let Some(frame) = group.frame
        {
            return Some(frame);
        }
        self.store_frame(store)
    }

    /// Whether `player_id`'s rig is measured in its store's own frame (every rig but a far
    /// group's in free flight).
    fn in_store_frame(&self, player_id: PlayerId) -> bool {
        self.store_of(player_id) != StoreKey::Space
            || self
                .space_groups()
                .into_iter()
                .find(|group| group.members.contains(&player_id))
                .is_none_or(|group| group.frame.is_none())
    }

    /// After the tick: each far group's rigs measured in its own frame again (their exact space
    /// positions say where; a rig that joined the first group is measured in the store's).
    fn settle_space_groups(&mut self) {
        let Some(store_frame) = self.store_frame(StoreKey::Space) else {
            return;
        };
        let groups = self.space_groups();
        if groups.len() < 2 {
            // Everyone in the store's frame: a rig a far group left behind (its position a
            // whole number of sectors off) is measured in it again. A rig already in it is
            // left exactly as it is.
            for group in &groups {
                for member in &group.members {
                    if let Some(rig) = self.players.get_mut(member)
                        && rig.flight.away()
                    {
                        let (x, y) = store_frame.local(rig.flight.pos);
                        if (rig.x - x).abs() > 1.0 || (rig.y - y).abs() > 1.0 {
                            rig.x = x;
                            rig.y = y;
                        }
                    }
                }
            }
            return;
        }
        for group in groups {
            let frame = group.frame.unwrap_or(store_frame);
            for member in group.members {
                if let Some(rig) = self.players.get_mut(&member)
                    && rig.flight.away()
                {
                    let (x, y) = frame.local(rig.flight.pos);
                    rig.x = x;
                    rig.y = y;
                }
            }
        }
    }

    /// A ground pass's frame moved to `frame` with only the store's things (its entities)
    /// following (a far group of free flight ticks in its own frame, Wave 13 QA).
    fn move_ground_entities(&mut self, frame: Frame) {
        let shift = self.terrain.frame().shift_to(frame);
        self.terrain.set_frame(frame);
        if !shift.is_zero() {
            self.entities.reframe_all(shift);
        }
    }

    /// The live players in `store`, in id order.
    pub fn players_in(&self, store: StoreKey) -> impl Iterator<Item = PlayerId> + '_ {
        self.players
            .keys()
            .copied()
            .filter(move |player| self.store_of(*player) == store)
    }

    /// The absolute position of `player_id`'s rig in its own store's frame.
    #[must_use]
    pub fn rig_world_pos(&self, player_id: PlayerId) -> Option<(Place, WorldPos)> {
        let player = self.players.get(&player_id)?;
        let frame = self.player_frame(player_id)?;
        Some((self.place_of(player_id), frame.world(player.x, player.y)))
    }

    /// Every awake region this tick would simulate, in order: the cells round every occupant
    /// of every occupied store (V11+ worlds), or one region per occupied store elsewhere.
    #[must_use]
    pub fn occupied_regions(&self) -> Vec<RegionId> {
        let mut regions = BTreeSet::new();
        for store in self.occupied_stores() {
            // Each rig in its own frame (free flight's far groups have theirs, Wave 13 QA).
            let tiles: Vec<TilePosition> = self
                .players_in(store)
                .filter_map(|player| {
                    let frame = self.player_frame(player)?;
                    self.actor_in(store, player)
                        .map(|(x, y)| frame.tile_at(x, y))
                })
                .collect();
            for (cell_x, cell_y) in occupied_cells(tiles) {
                regions.insert(RegionId {
                    store,
                    cell_x,
                    cell_y,
                });
            }
        }
        regions.into_iter().collect()
    }

    /// The stores with a live player in them, in key order (the home store always first).
    fn occupied_stores(&self) -> Vec<StoreKey> {
        let mut stores: BTreeSet<StoreKey> = BTreeSet::new();
        stores.insert(StoreKey::Home);
        for player in self.players.keys() {
            stores.insert(self.store_of(*player));
        }
        stores.into_iter().collect()
    }

    /// `player_id`'s actor in its own store (the pilot on foot, else the rig), outside the
    /// tick, and whether it is on foot.
    #[must_use]
    pub fn store_actor_position(&self, player_id: PlayerId) -> Option<(f32, f32, bool)> {
        let store = self.store_of(player_id);
        let entities = self.store_entities(store)?;
        if let Some(pilot) = entities.of_kind(EntityKind::Pilot).find(|entity| {
            matches!(&entity.state, crate::entity::EntityState::Pilot(state) if state.owner == player_id)
        }) && let crate::entity::EntityState::Pilot(state) = &pilot.state
        {
            let (x, y) = state.middle(&pilot.body);
            return Some((x, y, true));
        }
        self.players
            .get(&player_id)
            .map(|rig| (rig.x, rig.y, false))
    }

    /// `player`'s actor (the pilot on foot, else the rig) in `store`, outside the tick.
    fn actor_in(&self, store: StoreKey, player: PlayerId) -> Option<(f32, f32)> {
        let entities = self.store_entities(store)?;
        if let Some(pilot) = entities.of_kind(EntityKind::Pilot).find(|entity| {
            matches!(&entity.state, crate::entity::EntityState::Pilot(state) if state.owner == player)
        }) && let crate::entity::EntityState::Pilot(state) = &pilot.state
        {
            return Some(state.middle(&pilot.body));
        }
        self.players.get(&player).map(|rig| (rig.x, rig.y))
    }

    /// Moves `player_id` (its rig, and its pilot when on foot) to `place` at absolute position
    /// `position` in that place's frame, keeping cargo, fuel, hull, velocity, spin and every
    /// other piece of state; a drill in progress and a cart ride end. The destination's ground
    /// is created on first arrival and the chunks round the arrival point are generated at
    /// once. Used by landing and take-off (`world/body_flight.rs`), the beacon and the test-mode
    /// warp; safe online (it runs inside the
    /// tick on the host and in every client's prediction alike).
    ///
    /// Inside the tick the move is applied after the tick's last pass (so no pass sees a
    /// player half moved).
    ///
    /// # Errors
    ///
    /// [`PlaceError::UnknownPlayer`] for a player not in the world, and
    /// [`PlaceError::OutsideGround`] for a position outside the destination's ground.
    pub fn move_to_place(
        &mut self,
        player_id: PlayerId,
        place: Place,
        position: WorldPos,
    ) -> Result<(), PlaceError> {
        if !self.players.contains_key(&player_id) && !self.place_pass.running {
            return Err(PlaceError::UnknownPlayer);
        }
        if self.place_pass.running {
            self.place_pass
                .pending_moves
                .push((player_id, place, position));
            return Ok(());
        }
        self.apply_move(player_id, place, position)
    }

    fn apply_move(
        &mut self,
        player_id: PlayerId,
        place: Place,
        position: WorldPos,
    ) -> Result<(), PlaceError> {
        let Some(rig) = self.players.get(&player_id) else {
            return Err(PlaceError::UnknownPlayer);
        };
        let (old_x, old_y) = (rig.x, rig.y);
        let from = self.store_of(player_id);
        let to = place.store();
        self.ensure_store(to);
        if to != from && self.players_in(to).next().is_none() {
            // An empty store's floating frame moves to the arrival (nothing there moves in
            // absolute terms), so the arriving rig's local position is small and exact.
            if let Some(frame) = self.store_frame(to)
                && frame.floating()
            {
                self.move_store_frame(to, Frame::floating_at(position.sector_x, position.sector_y));
            }
        }
        let Some(frame) = self.store_frame(to) else {
            return Err(PlaceError::OutsideGround);
        };
        let (new_x, new_y) = frame.local(position);
        let arrival = frame.tile_at(new_x, new_y);
        if let Some(terrain) = self.store_terrain(to)
            && !terrain.contains_column(arrival.x)
        {
            return Err(PlaceError::OutsideGround);
        }
        let shift = FrameShift {
            dx: old_x - new_x,
            dy: old_y - new_y,
        };
        // The pilot on foot goes along, where it stood relative to the rig.
        if let Some(pilot) = self.take_entity_of(from, player_id, EntityKind::Pilot) {
            let mut pilot = pilot;
            pilot.reframe(shift);
            self.insert_entity_into(to, pilot);
        }
        if let Some(rig) = self.players.get_mut(&player_id) {
            rig.reframe(shift);
            rig.cart = None;
        }
        self.active_drills.remove(&player_id);
        self.active_drill_timers.remove(&player_id);
        if to.is_home() {
            self.places.players.remove(&player_id);
        } else {
            self.places.players.insert(player_id, place);
        }
        self.load_arrival_chunks(to, arrival);
        Ok(())
    }

    /// Creates `store`'s ground if nobody has been there yet (generated from the world seed).
    pub(crate) fn ensure_store(&mut self, store: StoreKey) {
        if store.is_home() || self.places.stores.contains_key(&store) {
            return;
        }
        let seed = self.world_seed();
        if let Some(world) = BodyWorld::generate(store, seed, Frame::FLOATING) {
            self.places.stores.insert(store, world);
        }
    }

    /// The world's seed (body generation reads it).
    pub(crate) const fn home_seed(&self) -> u64 {
        if self.place_pass.store.is_home() {
            self.terrain.seed()
        } else {
            self.place_pass.home_seed
        }
    }

    /// The home world's settings (the home terrain's, also inside another store's ground
    /// pass, whose terrain is the body's).
    #[must_use]
    pub(crate) fn home_settings(&self) -> crate::worldgen::WorldSettings {
        if self.place_pass.store.is_home() {
            *self.terrain.settings()
        } else {
            self.place_pass
                .home_settings
                .unwrap_or_else(|| *self.terrain.settings())
        }
    }

    /// The home world's frame (also inside another store's ground pass).
    #[must_use]
    pub(crate) const fn home_frame(&self) -> Frame {
        if self.place_pass.store.is_home() {
            self.terrain.frame()
        } else {
            self.place_pass.home_frame
        }
    }

    /// Moves `store`'s frame to `frame`, shifting every position in that store (its entities
    /// and the rigs of its players) so nothing moves in absolute terms.
    pub(crate) fn move_store_frame(&mut self, store: StoreKey, frame: Frame) {
        if store == self.place_pass.store {
            if store.is_home() {
                self.move_frame(frame);
            } else {
                self.move_ground_frame(frame);
            }
            return;
        }
        // Free flight's far groups keep their own frames (Wave 13 QA): only the rigs measured
        // in the store's frame move with it.
        let players: Vec<PlayerId> = self
            .players_in(store)
            .filter(|player| store != StoreKey::Space || self.in_store_frame(*player))
            .collect();
        let Some(world) = self.places.stores.get_mut(&store) else {
            return;
        };
        // A round body's strip wraps: positions shift only by the nearest copy of `frame` round
        // it, as in the store's own pass (a frame relabelled by whole laps moves nothing).
        let shift = world
            .terrain
            .frame()
            .shift_to(super::planet::nearest_lap_frame_of(&world.terrain, frame));
        world.terrain.set_frame(frame);
        if shift.is_zero() {
            return;
        }
        world.entities.reframe_all(shift);
        for player in players {
            if let Some(rig) = self.players.get_mut(&player) {
                rig.reframe(shift);
            }
        }
        self.reframe_parked_in(store, shift);
    }

    /// Shifts the rigs (and pilots) of the players parked in `store` with its frame, so a
    /// player who comes back finds its rig where it left it.
    fn reframe_parked_in(&mut self, store: StoreKey, shift: FrameShift) {
        let places = &self.places;
        for (id, parked) in &mut self.crew.parked {
            if places
                .players
                .get(id)
                .is_some_and(|place| place.store() == store)
            {
                super::frame::reframe_parked_body(parked, shift);
            }
        }
    }

    /// A ground pass's frame move: only the store's own things move (its entities and the
    /// players in the pass); the world's places, homes and sites stay in the home frame.
    fn move_ground_frame(&mut self, next: Frame) {
        // A round body's strip wraps: positions shift only by the nearest copy of `next`
        // round it, and a frame relabelled by whole laps moves nothing (Wave 11 polar).
        let shift = self.terrain.frame().shift_to(self.nearest_lap_frame(next));
        self.terrain.set_frame(next);
        if shift.is_zero() {
            return;
        }
        self.entities.reframe_all(shift);
        for rig in self.players.values_mut() {
            rig.reframe(shift);
        }
        self.reframe_parked_in(self.place_pass.store, shift);
    }

    /// Removes `player`'s entity of `kind` (its pilot) from `store`.
    fn take_entity_of(
        &mut self,
        store: StoreKey,
        player: PlayerId,
        kind: EntityKind,
    ) -> Option<Entity> {
        let entities = if store == self.place_pass.store {
            &mut self.entities
        } else {
            &mut self.places.stores.get_mut(&store)?.entities
        };
        let id = entities
            .of_kind(kind)
            .find(|entity| {
                matches!(&entity.state, crate::entity::EntityState::Pilot(state) if state.owner == player)
            })?
            .id;
        entities.despawn(id)
    }

    /// Puts `entity` (with a fresh id from the shared counters) into `store`.
    #[allow(
        clippy::needless_pass_by_value,
        reason = "the entity moves stores: the old one is gone"
    )]
    fn insert_entity_into(&mut self, store: StoreKey, entity: Entity) {
        let tick = self.simulation_tick;
        let (next_id, next_revision) = (self.entities.next_id(), self.entities.next_revision());
        if store == self.place_pass.store {
            let _id = self
                .entities
                .spawn(tick, entity.body, entity.state, entity.expires_at);
            return;
        }
        let Some(world) = self.places.stores.get_mut(&store) else {
            return;
        };
        world.entities.set_counters(
            next_id.max(world.entities.next_id()),
            next_revision.max(world.entities.next_revision()),
        );
        let _id = world
            .entities
            .spawn(tick, entity.body, entity.state, entity.expires_at);
        let counters = (world.entities.next_id(), world.entities.next_revision());
        self.entities.set_counters(counters.0, counters.1);
    }

    /// Generates the chunks round an arrival at once.
    fn load_arrival_chunks(&mut self, store: StoreKey, arrival: TilePosition) {
        let radius = ARRIVAL_CHUNK_RADIUS * crate::terrain::CHUNK_SIZE_TILES;
        let centers = [
            arrival,
            TilePosition {
                x: arrival.x - radius,
                y: arrival.y,
            },
            TilePosition {
                x: arrival.x + radius,
                y: arrival.y,
            },
        ];
        if store == self.place_pass.store {
            let _loaded = self.terrain.stream_around(&centers);
        } else if let Some(world) = self.places.stores.get_mut(&store) {
            let _loaded = world.terrain.stream_around(&centers);
        }
    }

    /// Records `player_id` as being at `place` without moving anything (a replica following
    /// its authority's per-tick state, which is already in the place's frame).
    pub(crate) fn set_place_record(&mut self, player_id: PlayerId, place: Place) {
        let store = place.store();
        if store.is_home() {
            self.places.players.remove(&player_id);
        } else {
            self.ensure_store(store);
            self.places.players.insert(player_id, place);
        }
    }

    /// The place recorded for `player_id` (the home world when none: the Moon is not
    /// recorded, it is where a home-store actor stands).
    #[must_use]
    pub fn recorded_place(&self, player_id: PlayerId) -> Place {
        self.places
            .players
            .get(&player_id)
            .copied()
            .unwrap_or(Place::HOME)
    }

    /// The test-mode warp to `place` (F11): the place's arrival point (a body's generator's,
    /// a settled body's first alien town (Wave 12), the Moon's top, the spawn point at home,
    /// the origin of free flight), with full air.
    pub(super) fn warp_to_place(
        &mut self,
        player_id: PlayerId,
        place: Place,
    ) -> crate::summary::PlayerScopedCommandOutcome {
        use crate::summary::PlayerScopedCommandOutcome;
        let home_frame = if self.place_pass.store.is_home() {
            self.frame()
        } else {
            self.place_pass.home_frame
        };
        let arrival = match place {
            Place::OnBody(crate::place::BodyId::Home) => {
                home_frame.world(self.player_template.x, self.player_template.y)
            }
            Place::OnBody(crate::place::BodyId::Moon) => {
                let settings = if self.place_pass.store.is_home() {
                    *self.terrain.settings()
                } else {
                    self.place_pass
                        .home_settings
                        .unwrap_or_else(|| *self.terrain.settings())
                };
                let Some(moon) = crate::worldgen::sky::moon(&settings) else {
                    return PlayerScopedCommandOutcome::IgnoredUnavailable;
                };
                WorldPos::tile_center(i64::from(moon.center_x), i64::from(moon.top_row) - 4)
            }
            // A settled body (Wave 12): over its first alien town's square.
            Place::OnBody(crate::place::BodyId::Space(key))
                if let Some(params) = crate::place::planet_params_for(self.world_seed(), key)
                    && let Some(first) = crate::alien::town::towns_of(&params).first() =>
            {
                crate::world::strip_position(
                    f64::from(first.site.centre) + 0.5,
                    f64::from(first.ground_row() - 3),
                )
            }
            Place::OnBody(crate::place::BodyId::Space(_)) | Place::Space => {
                let Some(source) = BodySource::for_store(place.store(), self.home_seed()) else {
                    return PlayerScopedCommandOutcome::IgnoredUnavailable;
                };
                let tile = source.generator().arrival_tile();
                WorldPos::tile_center(i64::from(tile.x), i64::from(tile.y))
            }
        };
        // The warp arrives with full air (a round body's life support counts from there).
        let air = self.air_capacity_of(player_id);
        // A rig warped down onto a body stands landed there (the ground code drives it), one
        // warped home flies no more: a warp out of flight left it "away" on the ground, where
        // the body's rules never ran for it (Wave 12 integration).
        let landed = match place {
            Place::OnBody(crate::place::BodyId::Space(key)) => self
                .space()
                .body_ref(key)
                .map(crate::flight::FlightPlace::Landed),
            Place::OnBody(_) => Some(crate::flight::FlightPlace::Home),
            Place::Space => Some(crate::flight::FlightPlace::Space),
        };
        if let Some(player) = self.players.get_mut(&player_id) {
            player.flight.air = player.flight.air.max(air);
            if let Some(landed) = landed {
                player.flight.place = landed;
                player.flight.drive = crate::flight::StarDrive::Off;
                player.flight.velocity_x = 0.0;
                player.flight.velocity_y = 0.0;
            }
        }
        match self.move_to_place(player_id, place, arrival) {
            Ok(()) => PlayerScopedCommandOutcome::Applied,
            Err(PlaceError::UnknownPlayer) => PlayerScopedCommandOutcome::UnknownPlayer,
            Err(PlaceError::OutsideGround) => PlayerScopedCommandOutcome::IgnoredUnavailable,
        }
    }

    /// Runs `edit` with `store`'s ground swapped into the world (outside the tick only): tools,
    /// tests and generators that put things on a body (spawn helpers, tile writes and entity
    /// queries then work on that body's ground in its frame). `None` inside the tick or for a
    /// store nobody has been to.
    #[doc(hidden)]
    pub fn with_store_ground<R>(
        &mut self,
        store: StoreKey,
        edit: impl FnOnce(&mut Self) -> R,
    ) -> Option<R> {
        if self.place_pass.running {
            return None;
        }
        if store.is_home() {
            return Some(edit(self));
        }
        let mut world = self.places.stores.remove(&store)?;
        let (next_id, next_revision) = (self.entities.next_id(), self.entities.next_revision());
        world.entities.set_counters(
            next_id.max(world.entities.next_id()),
            next_revision.max(world.entities.next_revision()),
        );
        self.place_pass.home_seed = self.terrain.seed();
        self.place_pass.home_frame = self.terrain.frame();
        self.place_pass.home_settings = Some(*self.terrain.settings());
        self.swap_ground(&mut world);
        self.place_pass.store = store;
        let result = edit(self);
        self.place_pass.store = StoreKey::Home;
        let counters = (self.entities.next_id(), self.entities.next_revision());
        self.swap_ground(&mut world);
        self.entities.set_counters(counters.0, counters.1);
        self.places.stores.insert(store, world);
        Some(result)
    }

    // --- The tick over every occupied store ----------------------------------------------------

    /// The tick of a world with more than one store, or with regions (see the module docs).
    pub(super) fn simulate_places(
        &mut self,
        tick: SimulationTick,
        inputs: &TickInputs,
    ) -> TickOutput {
        let next_tick = tick.next();
        let others = self.stores_to_tick();
        let away: BTreeSet<PlayerId> = self
            .players
            .keys()
            .copied()
            .filter(|player| !self.store_of(*player).is_home())
            .collect();
        // The world pass: the home store, its players and every world-level system.
        let home_inputs = filter_inputs(inputs, |player| !away.contains(&player));
        let stash = self.stash_players(|player| away.contains(&player));
        self.place_pass.running = true;
        self.place_pass.store = StoreKey::Home;
        self.place_pass.ground_only = false;
        self.place_pass.regions = self.terrain.settings().generator.has_descents();
        self.place_pass.home_seed = self.terrain.seed();
        self.place_pass.home_frame = self.terrain.frame();
        self.place_pass.home_settings = Some(*self.terrain.settings());
        self.place_pass.awake_cells = self.awake_cells_here();
        let mut output = self.simulate_pass(tick, &home_inputs);
        self.restore_players(stash);
        // One ground pass per other occupied store.
        for store in others {
            // Free flight's far-apart groups each tick in their own frame (Wave 13 QA).
            let groups = if store == StoreKey::Space {
                self.space_groups()
            } else {
                Vec::new()
            };
            let passes: Vec<Option<&SpaceGroup>> = if groups.len() > 1 {
                groups.iter().map(Some).collect()
            } else {
                vec![None]
            };
            for group in passes {
                let mut store_output = self.simulate_store(store, tick, inputs, group);
                // Events are routed by place (Wave 13 QA): everything this pass raised is the
                // store's.
                store_output.stamp_stores(0, |_| store);
                output.merge_pass(store_output);
            }
        }
        // Space combat (Wave 12 hostiles) once a tick with every rig back from its store: free
        // flight's rigs live in the Space store, far flyers park in the home store, and the
        // ships fight them all on one clock (Wave 12 integration).
        self.place_pass.store = StoreKey::Home;
        self.place_pass.ground_only = false;
        let combat_from = output.events.len();
        self.advance_hostiles(inputs, next_tick, &mut output);
        // A fight's events are its rig's place's; a ship's own (no rig) are free flight's.
        let stores: BTreeMap<PlayerId, StoreKey> = self
            .players
            .keys()
            .map(|player| (*player, self.store_of(*player)))
            .collect();
        output.stamp_stores(combat_from, |kind| match kind {
            crate::event::GameplayEventKind::Hostile {
                player_id: Some(player),
                ..
            } => stores.get(player).copied().unwrap_or(StoreKey::Space),
            _ => StoreKey::Space,
        });
        // The endgame (Wave 13) with every rig back: landings, materials, quarries, the space
        // achievements.
        self.advance_endgame(&mut output);
        // The galaxy story (Wave 13 story) with every rig back, after the fights.
        self.advance_galaxy_story(&mut output);
        self.place_pass.running = false;
        self.place_pass.store = StoreKey::Home;
        self.place_pass.ground_only = false;
        self.place_pass.awake_cells = None;
        for (player, place, position) in std::mem::take(&mut self.place_pass.pending_moves) {
            let from = self.place_of(player);
            if self.apply_move(player, place, position).is_ok() && from != place {
                output.push_event(crate::event::GameplayEventKind::PlaceChanged {
                    player_id: player,
                    from,
                    to: place,
                });
                let at = output.events.len() - 1;
                output.stamp_stores(at, |_| place.store());
            }
        }
        // Each far group in free flight keeps its rigs in its own frame (Wave 13 QA).
        self.settle_space_groups();
        let _ = next_tick;
        output
    }

    /// The occupied stores other than the home store this tick serves, within the per-tick
    /// budget (round robin after the last one served when there are more).
    fn stores_to_tick(&mut self) -> Vec<StoreKey> {
        let occupied: Vec<StoreKey> = self
            .occupied_stores()
            .into_iter()
            .filter(|store| !store.is_home())
            .collect();
        if occupied.len() <= MAX_AWAKE_STORES_PER_TICK {
            if self.places.cursor.is_some() {
                self.places.cursor = None;
            }
            return occupied;
        }
        let start = self.places.cursor.map_or(0, |cursor| {
            occupied.partition_point(|store| *store <= cursor)
        });
        let chosen: Vec<StoreKey> = (0..MAX_AWAKE_STORES_PER_TICK)
            .map(|offset| occupied[(start + offset) % occupied.len()])
            .collect();
        self.places.cursor = chosen.last().copied();
        let mut chosen = chosen;
        chosen.sort();
        chosen
    }

    /// One ground pass over `store` with its players.
    fn simulate_store(
        &mut self,
        store: StoreKey,
        tick: SimulationTick,
        inputs: &TickInputs,
        group: Option<&SpaceGroup>,
    ) -> TickOutput {
        self.ensure_store(store);
        let Some(mut world) = self.places.stores.remove(&store) else {
            return TickOutput {
                tick,
                ..TickOutput::default()
            };
        };
        // One group of free flight's rigs (Wave 13 QA), or everyone in the store.
        let members: BTreeSet<PlayerId> = group.map_or_else(
            || self.players_in(store).collect(),
            |group| group.members.iter().copied().collect(),
        );
        let store_inputs = filter_inputs(inputs, |player| members.contains(&player));
        let stash = self.stash_players(|player| !members.contains(&player));
        // The store continues the world's entity counters (ids and revisions stay unique).
        let (next_id, next_revision) = (self.entities.next_id(), self.entities.next_revision());
        world.entities.set_counters(
            next_id.max(world.entities.next_id()),
            next_revision.max(world.entities.next_revision()),
        );
        self.swap_ground(&mut world);
        // Each body keeps its own map (Wave 12 systems): its players' discoveries are swapped
        // in with its ground and out again; the op log's discovery stays the home world's.
        let discovered = std::mem::replace(
            &mut self.discovered_tiles,
            std::mem::take(&mut world.discovered),
        );
        self.place_pass.store = store;
        self.place_pass.ground_only = true;
        // A far group of free flight ticks in its own frame round its rigs (exact wherever it
        // is), and only the store's things round it wake (each thing ticks once a tick).
        // The store's things as they stand: those the far pass leaves alone go back exactly
        // (a shift of millions of pixels there and back would round them to the far frame's
        // `f32` grid, every tick).
        let mut untouched: Vec<Entity> = Vec::new();
        let store_frame = group.and_then(|group| group.frame).map(|frame| {
            let home = self.terrain.frame();
            untouched = self.entities.iter().cloned().collect();
            self.move_ground_entities(frame);
            for member in &group.map_or_else(Vec::new, |group| group.members.clone()) {
                if let Some(rig) = self.players.get_mut(member)
                    && rig.flight.away()
                {
                    let (x, y) = frame.local(rig.flight.pos);
                    rig.x = x;
                    rig.y = y;
                }
            }
            home
        });
        self.place_pass.awake_cells = if group.is_some() {
            Some(self.occupied_cells_here())
        } else {
            self.awake_cells_here()
        };
        let mut output = self.simulate_pass(tick, &store_inputs);
        if let Some(home) = store_frame {
            self.move_ground_entities(home);
            self.entities.restore_unchanged(&untouched);
        }
        output.discoveries.clear();
        world.discovered = std::mem::replace(&mut self.discovered_tiles, discovered);
        for tiles in world.discovered.values_mut() {
            let _ = tiles.take_revealed();
        }
        let counters = (self.entities.next_id(), self.entities.next_revision());
        self.swap_ground(&mut world);
        self.entities.set_counters(counters.0, counters.1);
        self.places.stores.insert(store, world);
        self.restore_players(stash);
        // Ore dug here counts toward the quotas on this body (Wave 12 stations).
        self.credit_store_ore(store, &mut output);
        // Tile writes of this store travel tagged with it.
        output.store_terrain_ops = std::mem::take(&mut output.terrain_ops)
            .into_iter()
            .map(|change| (store, change))
            .collect();
        output
    }

    /// Swaps a store's ground with the world's own.
    const fn swap_ground(&mut self, world: &mut BodyWorld) {
        std::mem::swap(&mut self.terrain, &mut world.terrain);
        std::mem::swap(&mut self.entities, &mut world.entities);
        std::mem::swap(&mut self.fluids, &mut world.fluids);
        // The store's own field zones (a planet's gravity); the home world's stay out of it.
        std::mem::swap(&mut self.fields, &mut world.fields);
    }

    /// The awake cells round the occupants of the ground swapped in (`None` on worlds that do
    /// not tick by region).
    fn awake_cells_here(&self) -> Option<BTreeSet<(i64, i64)>> {
        if !self.ticks_by_region() {
            return None;
        }
        Some(self.occupied_cells_here())
    }

    /// The cells round the occupants of the ground swapped in.
    fn occupied_cells_here(&self) -> BTreeSet<(i64, i64)> {
        let frame = self.frame();
        let mut tiles: Vec<TilePosition> = self
            .players
            .values()
            .map(|rig| frame.tile_at(rig.x, rig.y))
            .collect();
        tiles.extend(
            self.pilots()
                .map(|(_, body, _)| frame.tile_at(body.x, body.y)),
        );
        occupied_cells(tiles)
    }

    /// Whether an entity at local `(x, y)` is frozen this pass (outside every awake region).
    pub(crate) fn frozen_at(&self, x: f32, y: f32) -> bool {
        self.place_pass.awake_cells.as_ref().is_some_and(|cells| {
            !cells.contains(&crate::place::cell_of(self.frame().tile_at(x, y)))
        })
    }

    /// Whether `player_id` is in the world: a live rig of the running pass, or one set aside
    /// for it because it is in another store this tick (F11). World-level cleanups that drop
    /// the state of players who left use this, not `players.contains_key`.
    #[must_use]
    pub(crate) fn player_in_world(&self, player_id: PlayerId) -> bool {
        self.players.contains_key(&player_id) || self.place_pass.set_aside.contains(&player_id)
    }

    /// Whether `player_id` has a move to another place queued this tick (it is on its way: the
    /// rest of the tick leaves it be).
    #[must_use]
    pub(crate) fn moving_places(&self, player_id: PlayerId) -> bool {
        self.place_pass
            .pending_moves
            .iter()
            .any(|(player, _, _)| *player == player_id)
    }

    /// The players set aside for the running pass (see [`Self::player_in_world`]).
    pub(crate) fn place_pass_set_aside(&self) -> BTreeSet<PlayerId> {
        self.place_pass.set_aside.clone()
    }

    /// Takes the players `away` accepts (and their drills) out of the world for a pass.
    fn stash_players(&mut self, away: impl Fn(PlayerId) -> bool) -> PassPlayers {
        let mut stash = PassPlayers::default();
        let ids: Vec<PlayerId> = self
            .players
            .keys()
            .copied()
            .filter(|id| away(*id))
            .collect();
        self.place_pass.set_aside = ids.iter().copied().collect();
        for id in ids {
            if let Some(player) = self.players.remove(&id) {
                stash.players.insert(id, player);
            }
            if let Some(drill) = self.active_drills.remove(&id) {
                stash.drills.insert(id, drill);
            }
            if let Some(timer) = self.active_drill_timers.remove(&id) {
                stash.timers.insert(id, timer);
            }
        }
        stash
    }

    fn restore_players(&mut self, stash: PassPlayers) {
        self.place_pass.set_aside.clear();
        self.players.extend(stash.players);
        self.active_drills.extend(stash.drills);
        self.active_drill_timers.extend(stash.timers);
    }

    /// Streams a ground pass's chunks round its players, a bounded number per tick.
    pub(super) fn stream_ground_near_players(&mut self) {
        let frame = self.frame();
        let mut centers: Vec<TilePosition> = self
            .players
            .values()
            .map(|player| frame.tile_at(player.x, player.y))
            .collect();
        centers.extend(
            self.pilots()
                .map(|(_, body, _)| frame.tile_at(body.x, body.y)),
        );
        let _loaded = self
            .terrain
            .stream_around_budgeted(&centers, STORE_STREAM_CHUNKS_PER_TICK);
    }

    /// A ground pass's frame follows its first player (only the store's own things move).
    pub(super) fn recentre_ground_frame(&mut self) {
        let frame = self.frame();
        if !frame.floating() {
            return;
        }
        let Some(anchor) = self.players.keys().next().copied() else {
            return;
        };
        let Some((x, y)) = self.actor_position(anchor) else {
            return;
        };
        // A round body's frame stays labelled within one lap of its strip (Wave 11 polar).
        let next = self.wrapped_frame(frame.recentred_on(x, y).unwrap_or(frame));
        if next != frame {
            self.move_ground_frame(next);
        }
    }

    // --- Replication ---------------------------------------------------------------------------

    /// The frames of the stores other than the home store a client sees (`None`: every store).
    #[must_use]
    pub fn store_frames(&self, viewer_store: Option<StoreKey>) -> Vec<(StoreKey, Frame)> {
        self.places
            .stores
            .iter()
            .filter(|(key, _)| viewer_store.is_none_or(|store| store == **key))
            .map(|(key, world)| (*key, world.terrain.frame()))
            .collect()
    }

    /// A replica follows its authority's store frames (creating the stores it has not seen).
    pub(crate) fn apply_store_frames(&mut self, frames: &[(StoreKey, Frame)]) {
        for (store, frame) in frames {
            if store.is_home() {
                continue;
            }
            if !self.places.stores.contains_key(store) {
                let seed = crate::space::SpaceSeed::new(self.terrain.seed(), self.space_generator);
                if let Some(world) = BodyWorld::generate(*store, seed, *frame) {
                    self.places.stores.insert(*store, world);
                }
                continue;
            }
            self.move_store_frame(*store, *frame);
        }
    }

    /// The `(id, revision)` of every entity of `store` within `radius` tiles of `center`
    /// (tiles in the store's frame; `None`: all), in id order.
    #[must_use]
    pub fn store_entity_revisions(
        &self,
        store: StoreKey,
        center: Option<(f32, f32)>,
        radius: Option<f32>,
    ) -> Vec<(crate::entity::EntityId, u64)> {
        if store.is_home() {
            return self.entity_revisions(center, radius);
        }
        let Some(world) = self.places.stores.get(&store) else {
            return Vec::new();
        };
        match (center, radius) {
            (Some((cx, cy)), Some(radius)) => {
                let (x, y, reach) = (cx * TILE_SIZE, cy * TILE_SIZE, radius * TILE_SIZE);
                world.entities.revisions(
                    Some((x - reach, y - reach, x + reach, y + reach)),
                    |ex, ey| crate::field::trig::hypot(ex - x, ey - y) <= reach,
                )
            }
            _ => world.entities.revisions(None, |_, _| true),
        }
    }

    /// The store holding entity `id` and its record (any store).
    #[must_use]
    pub fn placed_entity_record(&self, id: crate::entity::EntityId) -> Option<(StoreKey, Entity)> {
        if let Some(entity) = self.entity_record(id) {
            return Some((StoreKey::Home, entity));
        }
        self.places
            .stores
            .iter()
            .find_map(|(key, world)| world.entities.get(id).map(|entity| (*key, entity.clone())))
    }

    /// Applies replicated entities of any store (and despawns, wherever they are).
    pub fn apply_placed_entity_delta(
        &mut self,
        updates: Vec<(StoreKey, Entity)>,
        despawned: Vec<crate::entity::EntityId>,
    ) {
        let mut home = crate::entity::EntityDelta::default();
        let mut by_store: BTreeMap<StoreKey, crate::entity::EntityDelta> = BTreeMap::new();
        for id in despawned {
            if self.entities.contains(id) {
                home.despawned.push(id);
            } else if let Some((key, _)) = self
                .places
                .stores
                .iter()
                .find(|(_, world)| world.entities.contains(id))
            {
                by_store.entry(*key).or_default().despawned.push(id);
            }
        }
        for (store, entity) in updates {
            // An entity changing stores leaves its old one.
            if !store.is_home() && self.entities.contains(entity.id) {
                home.despawned.push(entity.id);
            }
            for (key, world) in &self.places.stores {
                if *key != store && world.entities.contains(entity.id) {
                    by_store.entry(*key).or_default().despawned.push(entity.id);
                }
            }
            if store.is_home() {
                home.updates.push(entity);
            } else {
                by_store.entry(store).or_default().updates.push(entity);
            }
        }
        if !home.is_empty() {
            self.apply_entity_delta(home);
        }
        for (store, delta) in by_store {
            self.ensure_store(store);
            if let Some(world) = self.places.stores.get_mut(&store) {
                world.entities.apply_delta(delta);
            }
        }
    }

    /// The tiles of `store`'s `chunk` that differ from generation.
    #[must_use]
    pub fn store_chunk(&self, store: StoreKey, chunk: ChunkPosition) -> TileDiffs {
        self.store_terrain(store)
            .map(|terrain| terrain.chunk_diffs(chunk))
            .unwrap_or_default()
    }

    /// Overwrites `store`'s `chunk` with a replicated copy.
    pub fn apply_store_chunk(&mut self, store: StoreKey, chunk: ChunkPosition, diffs: &TileDiffs) {
        if store.is_home() {
            self.apply_terrain_chunk(chunk, diffs);
            return;
        }
        self.ensure_store(store);
        if let Some(world) = self.places.stores.get_mut(&store) {
            world.terrain.apply_chunk_diffs(chunk, diffs);
        }
    }

    /// Applies one replicated tile write in `store`.
    pub fn apply_store_tile_change(&mut self, store: StoreKey, change: &TileChange) -> bool {
        if store.is_home() {
            return self.apply_tile_change(change);
        }
        self.ensure_store(store);
        self.places
            .stores
            .get_mut(&store)
            .is_some_and(|world| world.terrain.apply_tile_change(change))
    }

    /// Hashes the place registry and the stores `sees_store` accepts.
    pub(super) fn hash_places(
        &self,
        hash: &mut StateHasher,
        sees_store: &impl Fn(StoreKey) -> bool,
    ) {
        self.places.hash_into(
            hash,
            &|player| self.players.contains_key(&player),
            sees_store,
        );
    }
}

/// `inputs` with only the players `keep` accepts.
fn filter_inputs(inputs: &TickInputs, keep: impl Fn(PlayerId) -> bool) -> TickInputs {
    TickInputs {
        players: inputs
            .players
            .iter()
            .filter(|(player, _)| keep(**player))
            .map(|(player, input)| (*player, input.clone()))
            .collect(),
    }
}

#[cfg(test)]
mod regrown_ground_tests {
    //! A saved body whose generated ground has grown since the save (Wave 14 finish: the
    //! Wave 12 worlds' lairs) still loads, with every edit it had.

    use super::{BodyWorld, BodyWorldData};
    use crate::{
        place::StoreKey,
        planet::lairs::lair_of,
        position::Frame,
        space::{SpaceSeed, Theme},
        terrain::{ChunkPosition, PackedChunks, Terrain, TileDiffs, TileKind, TilePosition},
        worldgen::DEFAULT_WORLD_SEED,
    };

    #[test]
    fn a_saved_body_whose_old_edit_the_new_ground_now_matches_still_loads() {
        let seed = SpaceSeed::current(DEFAULT_WORLD_SEED);
        let id = crate::endgame::hunt::nearest_theme_world(seed, Theme::Jungle)
            .expect("a jungle world near home");
        let store = StoreKey::Body(id);
        let mut body = BodyWorld::generate(store, seed, Frame::FLOATING).expect("a body");
        let planet = *body.planet().expect("a planet");
        let lair = lair_of(&planet).expect("a lair");
        let (middle, row) = lair.middle();
        let middle = i32::try_from(middle).expect("column");
        // An ordinary edit: a tunnel tile above the hall's ceiling.
        let dug = TilePosition {
            x: middle,
            y: lair.top - 6,
        };
        assert_ne!(
            body.terrain.tile(dug).map(|tile| tile.kind),
            Some(TileKind::Air)
        );
        assert!(body.terrain.set_kind(dug, TileKind::Air));
        let mut edits = body.terrain.edited_chunk_diffs();
        assert_eq!(Terrain::edits_digest(&edits), body.terrain.digest());
        // A Wave 13 save also dug where the hall now is: its edit is the Air the new ground
        // now generates there itself.
        let tunnel = TilePosition { x: middle, y: row };
        let air = body.terrain.tile(tunnel).expect("loaded");
        assert_eq!(air.kind, TileKind::Air);
        let chunk = ChunkPosition::of(tunnel);
        let local = u32::try_from(ChunkPosition::local_index(tunnel)).expect("index");
        match edits.iter_mut().find(|(at, _)| *at == chunk) {
            Some((_, diffs)) => {
                let entries: Vec<_> = diffs.iter().chain([(local, air)]).collect();
                *diffs = TileDiffs::new(entries);
            }
            None => edits.push((chunk, TileDiffs::new([(local, air)]))),
        }
        let digest = Terrain::edits_digest(&edits);
        assert_ne!(digest, body.terrain.digest());
        let data = BodyWorldData {
            store,
            seed: seed.seed,
            space_generator: seed.generator,
            fingerprint: body.fingerprint(),
            digest,
            frame: body.terrain.frame(),
            packed: PackedChunks(edits),
            entities: body.entities.clone(),
            fluids: body.fluids.clone(),
            discovered: body.discovered.clone(),
        };
        let json = serde_json::to_string(&data).expect("save");
        let loaded: BodyWorld = serde_json::from_str(&json).expect("the old body loads");
        assert_eq!(
            loaded.terrain.tile(dug).map(|tile| tile.kind),
            Some(TileKind::Air),
            "the player's edit survives"
        );
        assert_eq!(loaded.terrain.digest(), body.terrain.digest());

        // A save whose edits did not arrive whole still fails.
        let mut broken: serde_json::Value = serde_json::from_str(&json).expect("json");
        broken["digest"] = serde_json::json!(digest.wrapping_add(1));
        assert!(serde_json::from_value::<BodyWorld>(broken).is_err());
    }
}
